def triples_sum_to_zero(l: list) -> bool:
    n = len(l)
    if n < 3:
        return False
    l.sort()
    for i in range(n - 2):
        a = l[i]
        left, right = i + 1, n - 1
        while left < right:
            b, c = l[left], l[right]
            total = a + b + c
            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1
    return False

